"""Author the Grade 8 graph-from-table source and deterministic scene data.

Every question below was written for Athena. The linked CAPS ATP establishes
scope; no external exercise text is reproduced.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "docs/curriculum/grade8/graphs"

# prompt, row pairs, mode, four teaching actions, full verification, misconception,
# repair, axis data. Points are given only in questions that ask learners to read.
EXAMPLES = [
    ("Plot the table x: 0, 1, 2 and y: 1, 2, 3. Draw the straight-line graph.", [(0,1),(1,2),(2,3)], "line", ["Match x = 0 with y = 1; plot (0, 1).", "Match x = 1 with y = 2; plot (1, 2).", "Match x = 2 with y = 3; plot (2, 3).", "The three points align; draw the straight line through them."], "The pairs are (0, 1), (1, 2), (2, 3). They satisfy y = x + 1, so the graph is the straight line through all three.", "Putting all x values on one axis without matching their y row", "Point to one table column and read its x and y together.", 1, 1),
    ("For y = 2x + 2, complete the table at x = −1, 0, 1 and plot the graph.", [(-1,0),(0,2),(1,4)], "line", ["Substitute −1: 2(−1) + 2 = 0; plot (−1, 0).", "Substitute 0: 2(0) + 2 = 2; plot (0, 2).", "Substitute 1: 2(1) + 2 = 4; plot (1, 4).", "Each step right adds two vertically; draw one straight line."], "The outputs are 0, 2 and 4, giving (−1, 0), (0, 2), (1, 4); all satisfy y = 2x + 2.", "Dropping the negative sign when substituting −1", "Evaluate 2(−1) before adding 2 and check the x-axis crossing.", 1, 1),
    ("The table has x: 0, 2, 4 and y: 3, 3, 3. Plot it and describe the graph.", [(0,3),(2,3),(4,3)], "line", ["Read the first column: (0, 3).", "Read the second column: (2, 3).", "Read the third column: (4, 3).", "Join the three points horizontally at y = 3."], "Every output is 3. The graph is the horizontal line y = 3 through (0, 3), (2, 3), (4, 3).", "Drawing a vertical line because the output stays fixed", "Keep the y-guide at 3 while x moves; the line is horizontal.", 1, 1),
    ("For y = 5 − x, plot the entries x: 0, 2, 4 and describe the direction.", [(0,5),(2,3),(4,1)], "line", ["At x = 0, y = 5; plot (0, 5).", "At x = 2, y = 3; plot (2, 3).", "At x = 4, y = 1; plot (4, 1).", "Draw the falling straight line and read the change."], "The graph falls two y-units for every two x-units: pairs (0, 5), (2, 3), (4, 1) all satisfy y = 5 − x.", "Adding x to 5 instead of subtracting", "Check y at x = 4 by calculating 5 − 4 explicitly.", 1, 1),
    ("Plot y = 2x for x = −2, 0, 2. State where it crosses the axes.", [(-2,-4),(0,0),(2,4)], "line", ["Multiply −2 by 2: plot (−2, −4).", "Multiply 0 by 2: plot the origin (0, 0).", "Multiply 2 by 2: plot (2, 4).", "Join the points through (0, 0) and check the crossing."], "The straight graph passes through the origin, which is its crossing with both axes; the pairs satisfy y = 2x.", "Treating 2(−2) as positive four", "Use signed multiplication before plotting the left point.", 1, 1),
    ("Plot y = 2 − x for x = −1, 1, 3. Explain the downward trend.", [(-1,3),(1,1),(3,-1)], "line", ["At −1, calculate 2 − (−1) = 3.", "At 1, calculate 2 − 1 = 1.", "At 3, calculate 2 − 3 = −1.", "Plot all three and draw the descending straight line."], "The pairs are (−1, 3), (1, 1), (3, −1); each rise of two in x reduces y by two.", "Misreading 2 − (−1) as 1", "Write subtraction of a negative as addition, then check each plotted pair.", 1, 1),
    ("Complete y = 3x + 1 for x = 0, 1, 2, then plot and join the points.", [(0,1),(1,4),(2,7)], "line", ["Replace x by 0: y = 1; plot (0, 1).", "Replace x by 1: y = 4; plot (1, 4).", "Replace x by 2: y = 7; plot (2, 7).", "Draw the line; each x increase of one adds three to y."], "Outputs 1, 4, 7 form (0, 1), (1, 4), (2, 7), all on y = 3x + 1.", "Using 3(x + 1) rather than 3x + 1", "Multiply x first; add one only afterwards.", 1, 1),
    ("A table shows x: 0, 1, 2 and y: 4, 3, 2. Plot the pairs, not their reversed forms.", [(0,4),(1,3),(2,2)], "line", ["The first column is (0, 4), on the y-axis.", "The second column is (1, 3), not (3, 1).", "The third column is (2, 2).", "Join the falling points and read back all columns."], "The graph uses (0, 4), (1, 3), (2, 2), satisfying y = 4 − x.", "Reversing the input-output ordered pairs", "Place each column as (input, output) and project to both axes.", 1, 1),
    ("x ticks count by 2 and y ticks by 5. Plot table pairs (0, 0), (2, 5), (4, 10).", [(0,0),(2,5),(4,10)], "line", ["Read the x and y labels separately; plot (0, 0).", "One x interval is two and one y interval is five, giving (2, 5).", "Two x intervals give four and two y intervals give ten, giving (4, 10).", "Join the aligned points; verify their numeric labels."], "The plotted pairs (0, 0), (2, 5), (4, 10) form a straight line; one grid square represents different values on the two axes.", "Using one unit per square on both axes", "Read the marked ticks before counting squares on either axis.", 2, 5),
    ("The graph shows P at (0, 1), Q at (1, 3), R at (2, 5). Build the corresponding x/y table.", [(0,1),(1,3),(2,5)], "given_line", ["Project P: x = 0, y = 1; write the first table column.", "Project Q: x = 1, y = 3; write the next column.", "Project R: x = 2, y = 5; write the final column.", "Read the columns in increasing x order and check y = 2x + 1."], "The table has x: 0, 1, 2 and y: 1, 3, 5. The visible points satisfy y = 2x + 1.", "Reading graph points in label order without pairing x and y", "Project each dot to its two labelled axes before entering a column.", 1, 1),
    ("A learner plots y = 2x + 1 at (0, 1), (1, 3), (2, 4). Find and repair the wrong point.", [(0,1),(1,3),(2,5)], "error", ["Check x = 0: 2(0) + 1 = 1, so the first dot is right.", "Check x = 1: 2(1) + 1 = 3, so the second dot is right.", "At x = 2, 2(2) + 1 = 5, not 4.", "Keep the incorrect dot visible and correct it to (2, 5)."], "The first wrong point is (2, 4); replace it with (2, 5). The three correct points lie on y = 2x + 1.", "Stopping at multiplication and forgetting the final +1", "Calculate 2(2) + 1 in two separate operations, then compare with the learner dot.", 1, 1),
    ("Each whole ticket costs R5 plus one R10 booking fee. Plot total cost for 0, 1, 2 tickets. Should the dots be joined?", [(0,10),(1,15),(2,20)], "discrete", ["Zero tickets still incurs the R10 booking fee: (0, 10).", "One ticket costs 10 + 5 = 15: plot (1, 15).", "Two tickets cost 10 + 10 = 20: plot (2, 20).", "Keep separate dots: half a whole ticket is not an allowed input."], "At x = 0, 1, 2 the totals are R10, R15, R20. Whole tickets give discrete points; do not imply fractional tickets by joining them.", "Joining discrete points and suggesting half a ticket", "Ask whether x = 1.5 tickets is permitted before drawing any connecting line.", 1, 5),
    ("A temperature graph uses time 0, 2, 4 hours and values 2, 5, 8 °C. Plot and draw the measured straight trend.", [(0,2),(2,5),(4,8)], "line", ["Label time on x and temperature on y; plot (0, 2).", "At 2 hours the temperature is 5 °C; plot (2, 5).", "At 4 hours the temperature is 8 °C; plot (4, 8).", "Draw the straight trend through the measured points."], "The measured pairs are (0, 2), (2, 5), (4, 8), with a rise of 3 °C every 2 hours across the sampled interval.", "Swapping the time and temperature axes", "Read units beside both axes and interpret (2, 5) aloud.", 2, 1),
    ("The rule y = 3x + 1 gives (0, 1), (1, 4), (2, 7). Predict and plot the next point at x = 3.", [(0,1),(1,4),(2,7),(3,10)], "line", ["Plot the known pair (0, 1).", "Plot (1, 4) and (2, 7), retaining the first dot.", "Extend the table: y = 3(3) + 1 = 10.", "Plot (3, 10), draw the line and verify it follows the rule."], "At x = 3 the next output is 10, so (3, 10) extends the same straight line y = 3x + 1.", "Extending the x pattern but leaving y at 7", "Use the rule, not just the diagram, to calculate the new output.", 1, 1),
    ("Table x: 0, 1, 2, 3; y: 0, 1, 4, 9. Plot all pairs. Is one straight line through them justified?", [(0,0),(1,1),(2,4),(3,9)], "nonlinear", ["Plot (0, 0) from the first column.", "Plot (1, 1) and (2, 4) from their own columns.", "Plot (3, 9); keep the previous dots visible.", "Compare rises 1, 3, 5: they differ, so reject one straight line."], "The pairs (0, 0), (1, 1), (2, 4), (3, 9) have unequal rises 1, 3, 5 for equal x-steps. Do not draw a single straight line through them.", "Forcing any table into a straight-line graph", "Compare successive y-differences for equal x-steps before choosing a straight line.", 1, 1),
]

def main():
    OUT.mkdir(parents=True, exist_ok=True)
    scenes=[]
    doc=["# Grade 8 Graphs Lesson 2 — Tables to graphs and graphs to tables", "", "**Status:** Athena-authored source; teacher review required. These are original questions, not copied exercises.", "", "CAPS scope: plot points from tables or ordered pairs and draw graphs on the Cartesian plane. [2026 DBE Grade 8 ATP](https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf). [Siyavula topic outline](https://www.siyavula.com/read/za/mathematics/grade-8/graphs/23-graphs-06).", "", "The question's table is the source of truth. The board plots one matched column at a time, keeps earlier points visible, and draws a line only where the input domain and data justify one. A given graph is visible initially without revealing its coordinate answers. A learner error remains visible beside its correction.", "", "## Worked examples", ""]
    for n,(prompt,pairs,mode,actions,memo,mistake,repair,xt,yt) in enumerate(EXAMPLES,1):
        qid=f"g8-graphs-l02-w{n:02}"
        labels=[chr(65+i) for i in range(len(pairs))]
        given=mode=="given_line"
        derived=[] if given else [dict(label=label,x=x,y=y,reveal_step=min(i+1,3) if n!=14 else min(i+1,3)) for i,(label,(x,y)) in enumerate(zip(labels,pairs))]
        # In example 14 the fourth point is the predicted result, revealed on step 4.
        if n==14: derived[-1]["reveal_step"]=4
        erroneous=[dict(label="Learner C",x=2,y=4,error=True,coordinates_hidden=True)] if mode=="error" else []
        if mode=="error": derived[2]["reveal_step"]=4
        ymin=min(0,*[y for x,y in pairs])-yt*2
        ymax=max(0,*[y for x,y in pairs])+yt*2
        xmin=min(0,*[x for x,y in pairs])-xt*2
        xmax=max(0,*[x for x,y in pairs])+xt*2
        scene=dict(id=qid, axis=dict(x_min=xmin,x_max=xmax,y_min=ymin,y_max=ymax,x_tick=xt,y_tick=yt),given=[dict(label=label,x=x,y=y,coordinates_hidden=True) for label,(x,y) in zip(labels,pairs)] if given else erroneous,derived=derived,
                   graph=dict(mode=mode,line_reveal_step=4,table=[dict(x=x,y=y) for x,y in pairs],points=[dict(x=x,y=y) for x,y in pairs]), operation="table_to_graph", actions=actions, memo=memo, misconception=mistake, repair=repair, problem=prompt, marks=min(7,2+(n//3)))
        if n==12:scene["axis"].update(x_unit="tickets",y_unit="R")
        if n==13:scene["axis"].update(x_unit="hours",y_unit="°C")
        scenes.append(scene)
        doc += [f"### {n:02} — {'foundation' if n==1 else 'easy' if n<=3 else 'standard' if n<=6 else 'intermediate' if n<=9 else 'exam' if n<=12 else 'advanced'}", "", f"**Question ({scene['marks']} marks):** {prompt}", "", f"**Whiteboard:** Axis x [{xmin}, {xmax}] by {xt}; y [{ymin}, {ymax}] by {yt}. Mode: {mode}. Initial dots: {', '.join(p['label'] for p in scene['given']) or 'none'}. Plot stages: "+"; ".join(f"{p['label']} ({p['x']}, {p['y']}) at step {p['reveal_step']}" for p in derived)+". All earlier dots remain. The line appears on step 4 only for a continuous straight relationship.", "", "**Teaching sequence:** "+" → ".join(actions), "", f"**Full memo:** {memo}", "", f"**Misconception:** {mistake}. **Repair:** {repair}", ""]
    doc += ["## Independent practice and assessments", "", "Practice, mastery and reassessment have separate answer keys in the backend. The answer stays hidden until submission. Each item must return a topic-specific worked explanation and a changed-value retry after a misconception.", "", "## Acceptance", "", "Check all 15 scenes against their tables, scales and domains. Replay/Previous/Next reconstruct exactly the same persistent dots. For discrete tickets and nonlinear data, no straight line is drawn. Confirm phone-width tick labels and answer gating. Teacher sign-off is required before release approval."]
    (OUT/"lesson-02-tables-to-graphs.md").write_text("\n".join(doc)+"\n",encoding="utf-8")
    (OUT/"lesson-02-scenes.json").write_text(json.dumps(dict(lesson_id="g8-graphs-02",status="draft_teacher_review_required",scenes=scenes),ensure_ascii=False,indent=2)+"\n",encoding="utf-8")

if __name__=="__main__":main()
